{"command":"cat > /workspace/src/log.rs <<'EOF'
//! Minimal structured logger that mimics the default `tracing-subscriber`
//! formatter used by the original tool.
//!
//! Lines look like:
//! `2022-01-01T00:00:00.000000Z  INFO span{field=value}: target: message key=value`

use std::fmt;
use std::io::Write;
use std::sync::OnceLock;
use std::time::{SystemTime, UNIX_EPOCH};

/// Verbosity level of a log event.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

impl Level {
    fn padded(self) -> &'static str {
        match self {
            Level::Trace => "TRACE",
            Level::Debug => "DEBUG",
            Level::Info => " INFO",
            Level::Warn => " WARN",
            Level::Error => "ERROR",
        }
    }

    fn color(self) -> &'static str {
        match self {
            Level::Trace => "\x1b[35m",
            Level::Debug => "\x1b[34m",
            Level::Info => "\x1b[32m",
            Level::Warn => "\x1b[33m",
            Level::Error => "\x1b[31m",
        }
    }
}

/// A single filtering directive, e.g. `target[{field}]=level`.
#[derive(Clone, Debug)]
struct Directive {
    target: Option<String>,
    fields: Vec<String>,
    /// Maximum enabled level; 0 means "off".
    level: u8,
}

impl Directive {
    fn applies(&self, target: &str, fields: Option<&[&str]>) -> bool {
        if let Some(t) = &self.target {
            if !target.starts_with(t.as_str()) {
                return false;
            }
        }
        if let Some(fields) = fields {
            for name in &self.fields {
                if !fields.contains(&name.as_str()) {
                    return false;
                }
            }
        }
        true
    }

    /// Sorting key: more specific directives come first.
    fn specificity(&self) -> (Option<usize>, usize) {
        (self.target.as_ref().map(|t| t.len()), self.fields.len())
    }

    fn same_key(&self, other: &Directive) -> bool {
        self.target == other.target && self.fields == other.fields
    }
}

struct ParseError(String);

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

const LEVEL_ERR: &str = "error parsing level filter: expected one of \"off\", \"error\", \"warn\", \"info\", \"debug\", \"trace\", or a number 0-5";

fn parse_level(s: &str) -> Option<u8> {
    if let Ok(n) = s.parse::<usize>() {
        if n <= 5 {
            return Some(n as u8);
        }
    }
    let lv = match s {
        "" => 1,
        s if s.eq_ignore_ascii_case("error") => 1,
        s if s.eq_ignore_ascii_case("warn") => 2,
        s if s.eq_ignore_ascii_case("info") => 3,
        s if s.eq_ignore_ascii_case("debug") => 4,
        s if s.eq_ignore_ascii_case("trace") => 5,
        s if s.eq_ignore_ascii_case("off") => 0,
        _ => return None,
    };
    Some(lv)
}

fn parse_directive(s: &str) -> Result<Directive, ParseError> {
    let mut split = s.split('=');
    let part0 = split.next().unwrap_or("");
    if let Some(part1) = split.next() {
        if split.next().is_some() {
            return Err(ParseError(
                "invalid filter directive: too many '=' in filter directive, expected 0 or 1"
                    .into(),
            ));
        }
        let mut split = part0.split("[{");
        let target = split.next().map(String::from);
        let mut fields = Vec::new();
        if let Some(maybe_fields) = split.next() {
            if split.next().is_some() {
                return Err(ParseError(
                    "invalid filter directive: too many '[{' in filter directive, expected 0 or 1"
                        .into(),
                ));
            }
            if !maybe_fields.ends_with("}]") {
                return Err(ParseError(
                    "invalid filter directive: expected fields list to end with '}]'".into(),
                ));
            }
            fields.extend(
                maybe_fields
                    .trim_end_matches("}]")
                    .split(',')
                    .filter(|s| !s.is_empty())
                    .map(String::from),
            );
        }
        let level = parse_level(part1).ok_or_else(|| ParseError(LEVEL_ERR.into()))?;
        return Ok(Directive {
            target,
            fields,
            level,
        });
    }
    Ok(match parse_level(part0) {
        Some(level) => Directive {
            target: None,
            fields: Vec::new(),
            level,
        },
        None => Directive {
            target: Some(part0.to_string()),
            fields: Vec::new(),
            level: 5,
        },
    })
}

fn parse_filter(s: &str) -> Result<Vec<Directive>, ParseError> {
    let mut set: Vec<Directive> = Vec::new();
    for part in s.split(',') {
        let d = parse_directive(part)?;
        if let Some(existing) = set.iter_mut().find(|e| e.same_key(&d)) {
            *existing = d;
        } else {
            set.push(d);
        }
    }
    // Most specific first; ties broken lexicographically (descending) like the
    // reference implementation, which is not semantically important.
    set.sort_by(|a, b| {
        b.specificity()
            .cmp(&a.specificity())
            .then_with(|| b.target.cmp(&a.target))
            .then_with(|| b.fields.cmp(&a.fields))
    });
    Ok(set)
}

struct Config {
    ansi: bool,
    directives: Vec<Directive>,
}

static CONFIG: OnceLock<Config> = OnceLock::new();

/// Initialize the global logger from the environment (`RUST_LOG`, `NO_COLOR`).
pub fn init() {
    let ansi = match std::env::var_os("NO_COLOR") {
        Some(v) => v.is_empty(),
        None => true,
    };
    let directives = match std::env::var("RUST_LOG") {
        Ok(var) => match parse_filter(&var) {
            Ok(d) => d,
            Err(e) => {
                eprintln!("Ignoring `RUST_LOG={:?}`: {}", var, e);
                Vec::new()
            }
        },
        Err(_) => vec![Directive {
            target: None,
            fields: Vec::new(),
            level: 3,
        }],
    };
    let _ = CONFIG.set(Config { ansi, directives });
}

fn config() -> &'static Config {
    CONFIG.get_or_init(|| Config {
        ansi: true,
        directives: vec![Directive {
            target: None,
            fields: Vec::new(),
            level: 3,
        }],
    })
}

/// Whether a callsite with the given metadata is enabled. `fields` is `None`
/// for spans (field filters only apply to events).
fn enabled(level: Level, target: &str, fields: Option<&[&str]>) -> bool {
    let cfg = config();
    match cfg.directives.iter().find(|d| d.applies(target, fields)) {
        Some(d) => d.level >= level as u8,
        None => false,
    }
}

/// A recorded field value.
pub enum Value {
    /// Formatted with `Display`/`Debug` semantics that yield no quoting.
    Raw(String),
}

impl Value {
    fn as_str(&self) -> &str {
        match self {
            Value::Raw(s) => s,
        }
    }
}

/// Construct a raw (display-formatted) field value.
pub fn val<T: fmt::Display>(v: T) -> Value {
    Value::Raw(v.to_string())
}

fn write_fields(out: &mut String, ansi: bool, message: Option<&str>, fields: &[(&str, Value)]) {
    let mut first = true;
    if let Some(m) = message {
        out.push_str(m);
        first = false;
    }
    for (name, value) in fields {
        if !first {
            out.push(' ');
        }
        first = false;
        if ansi {
            out.push_str("\x1b[3m");
            out.push_str(name);
            out.push_str("\x1b[0m\x1b[2m=\x1b[0m");
        } else {
            out.push_str(name);
            out.push('=');
        }
        out.push_str(value.as_str());
    }
}

/// A tracing span (a named context with fields attached to each event).
#[derive(Clone)]
pub struct Span {
    /// Pre-rendered `name{fields}` for plain and ANSI output, or `None` if the
    /// span is disabled by the filter.
    rendered: Option<(String, String)>,
}

impl Span {
    /// Create a new INFO-level span.
    pub fn new(target: &str, name: &str, fields: &[(&str, Value)]) -> Span {
        if !enabled(Level::Info, target, None) {
            return Span { rendered: None };
        }
        let mut plain = String::from(name);
        let mut colored = format!("\x1b[1m{}\x1b[0m", name);
        if !fields.is_empty() {
            let mut p = String::new();
            write_fields(&mut p, false, None, fields);
            plain.push('{');
            plain.push_str(&p);
            plain.push('}');
            let mut c = String::new();
            write_fields(&mut c, true, None, fields);
            colored.push_str("\x1b[1m{\x1b[0m");
            colored.push_str(&c);
            colored.push_str("\x1b[1m}\x1b[0m");
        }
        Span {
            rendered: Some((plain, colored)),
        }
    }

    /// The empty (root) span.
    pub fn none() -> Span {
        Span { rendered: None }
    }
}

fn timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs() as i64;
    let micros = now.subsec_micros();
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // Civil-from-days algorithm (Howard Hinnant).
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        y, mo, d, h, m, s, micros
    )
}

/// Emit an event.
pub fn event(level: Level, span: &Span, target: &str, message: &str, fields: &[(&str, Value)]) {
    let mut names: Vec<&str> = Vec::with_capacity(fields.len() + 1);
    names.push("message");
    names.extend(fields.iter().map(|(n, _)| *n));
    if !enabled(level, target, Some(&names)) {
        return;
    }
    let ansi = config().ansi;
    let mut out = String::with_capacity(128);
    let ts = timestamp();
    if ansi {
        out.push_str("\x1b[2m");
        out.push_str(&ts);
        out.push_str("\x1b[0m ");
        out.push_str(level.color());
        out.push_str(level.padded());
        out.push_str("\x1b[0m ");
    } else {
        out.push_str(&ts);
        out.push(' ');
        out.push_str(level.padded());
        out.push(' ');
    }
    if let Some((plain, colored)) = &span.rendered {
        if ansi {
            out.push_str(colored);
            out.push_str("\x1b[2m:\x1b[0m ");
        } else {
            out.push_str(plain);
            out.push_str(": ");
        }
    }
    if ansi {
        out.push_str("\x1b[2m");
        out.push_str(target);
        out.push_str("\x1b[0m\x1b[2m:\x1b[0m ");
    } else {
        out.push_str(target);
        out.push_str(": ");
    }
    write_fields(&mut out, ansi, Some(message), fields);
    out.push('\n');
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

pub fn trace(span: &Span, target: &str, message: &str, fields: &[(&str, Value)]) {
    event(Level::Trace, span, target, message, fields)
}

pub fn info(span: &Span, target: &str, message: &str, fields: &[(&str, Value)]) {
    event(Level::Info, span, target, message, fields)
}

pub fn warn(span: &Span, target: &str, message: &str, fields: &[(&str, Value)]) {
    event(Level::Warn, span, target, message, fields)
}

pub fn error(span: &Span, target: &str, message: &str, fields: &[(&str, Value)]) {
    event(Level::Error, span, target, message, fields)
}
EOF
echo done"}

