                    let frame = match self.decode_eof() {
                        Ok(f) => f,
                        Err(e) => {
                            self.trace_framed("Got an error, going to errored state");
                            self.has_errored = true;
                            return Err(RecvError::Codec(e));
                        }
                    };
                    if frame.is_none() {
                        self.is_readable = false;
                    }
                    return Ok(frame);
                }
