/// Error returned when an operation exceeds its deadline.
#[derive(Debug)]
pub struct Elapsed;

impl fmt::Display for Elapsed {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("deadline has elapsed")
    }
}

impl std::error::Error for Elapsed {}

/// Errors produced by the null-delimited frame codec.
#[derive(Debug)]
pub enum CodecError {
    /// A frame exceeded the maximum allowed length.
    MaxChunkLengthExceeded,
    /// The underlying transport failed.
    Io(io::Error),
}

impl fmt::Display for CodecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CodecError::MaxChunkLengthExceeded => f.write_str("max chunk length exceeded"),
            CodecError::Io(e) => write!(f, "{}", e),
        }
    }
}

impl std::error::Error for CodecError {}

enum RecvError {
    Codec(CodecError),
    Timeout,
}

/// Transport stream with JSON frames delimited by null characters.
pub struct Delimited {
    stream: TcpStream,
    buf: Vec<u8>,
    next_index: usize,
    is_discarding: bool,
    eof: bool,
    is_readable: bool,
    has_errored: bool,
    span: Span,
}

impl Delimited {
    /// Construct a new delimited stream.
    pub fn new(stream: TcpStream, span: Span) -> Self {
        Self {
            stream,
            buf: Vec::new(),
            next_index: 0,
            is_discarding: false,
            eof: false,
            is_readable: false,
            has_errored: false,
            span,
        }
    }

    fn trace_framed(&self, msg: &str) {
        log::trace(&self.span, FRAMED_TARGET, msg, &[]);
    }

    /// Try to decode a single frame from the buffer.
    fn decode(&mut self) -> Result<Option<Vec<u8>>, CodecError> {
        loop {
            let read_to = std::cmp::min(MAX_FRAME_LENGTH.saturating_add(1), self.buf.len());
            let offset = if self.next_index <= read_to {
                self.buf[self.next_index..read_to].iter().position(|&b| b == 0)
            } else {
                None
            };
            match (self.is_discarding, offset) {
                (true, Some(offset)) => {
                    self.buf.drain(..offset + self.next_index + 1);
                    self.is_discarding = false;
                    self.next_index = 0;
                }
                (true, None) => {
                    self.buf.drain(..read_to);
                    self.next_index = 0;
                    if self.buf.is_empty() {
                        return Ok(None);
                    }
                }
                (false, Some(offset)) => {
                    let idx = offset + self.next_index;
                    self.next_index = 0;
                    let mut chunk: Vec<u8> = self.buf.drain(..idx + 1).collect();
                    chunk.pop();
                    return Ok(Some(chunk));
                }
                (false, None) if self.buf.len() > MAX_FRAME_LENGTH => {
                    self.is_discarding = true;
                    return Err(CodecError::MaxChunkLengthExceeded);
                }
                (false, None) => {
                    self.next_index = read_to;
                    return Ok(None);
                }
            }
        }
    }

    fn decode_eof(&mut self) -> Result<Option<Vec<u8>>, CodecError> {
        Ok(match self.decode()? {
            Some(frame) => Some(frame),
            None => {
                if self.buf.is_empty() {
                    None
                } else {
                    let chunk = std::mem::take(&mut self.buf);
                    self.next_index = 0;
                    Some(chunk)
                }
            }
        })
    }

    /// Read more data from the stream, honoring an optional deadline.
    fn fill(&mut self, deadline: Option<Instant>) -> Result<usize, RecvError> {
        let mut chunk = [0u8; READ_CHUNK];
        loop {
            if let Some(deadline) = deadline {
                let now = Instant::now();
                if now >= deadline {
                    return Err(RecvError::Timeout);
                }
                let remaining = deadline - now;
                let _ = self
                    .stream
                    .set_read_timeout(Some(remaining.max(Duration::from_millis(1))));
            }
            match self.stream.read(&mut chunk) {
                Ok(n) => {
                    self.buf.extend_from_slice(&chunk[..n]);
                    return Ok(n);
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e)
                    if deadline.is_some()
                        && (e.kind() == io::ErrorKind::WouldBlock
                            || e.kind() == io::ErrorKind::TimedOut) =>
                {
                    if Instant::now() >= deadline.unwrap() {
                        return Err(RecvError::Timeout);
                    }
                    continue;
                }
                Err(e) => return Err(RecvError::Codec(CodecError::Io(e))),
            }
        }
    }

    /// Poll the next frame, following the semantics of a framed reader.
    fn next_frame(&mut self, deadline: Option<Instant>) -> Result<Option<Vec<u8>>, RecvError> {
        loop {
            if self.has_errored {
                self.trace_framed("Returning None and setting paused");
                self.is_readable = false;
                self.has_errored = false;
                return Ok(None);
            }
            if self.is_readable {
                if self.eof {
                    let frame = match self.decode_eof() {
                        Ok(f) => f,
                        Err(e) => {
                            self.trace_framed("Got an error, going to errored state");
                            self.has_errored = true;
                            return Err(RecvError::Codec(e));
                        }
                    };
                    if frame.is_none() {
                        self.is_readable = false;
                    }
                    return Ok(frame);
                }
                self.trace_framed("attempting to decode a frame");
                match self.decode() {
                    Ok(Some(frame)) => {
                        self.trace_framed("frame decoded from buffer");
                        return Ok(Some(frame));
                    }
                    Ok(None) => {}
                    Err(e) => {
                        self.trace_framed("Got an error, going to errored state");
                        self.has_errored = true;
                        return Err(RecvError::Codec(e));
                    }
                }
                self.is_readable = false;
            }
            let n = match self.fill(deadline) {
                Ok(n) => n,
                Err(RecvError::Codec(e)) => {
