struct Transfer {
    buf: Box<[u8]>,
    pos: usize,
    cap: usize,
    read_done: bool,
    done: bool,
}

enum Want {
    Nothing,
    Read,
    Write,
}

impl Transfer {
    fn new() -> Self {
        Self {
            buf: vec![0u8; COPY_BUF].into_boxed_slice(),
            pos: 0,
            cap: 0,
            read_done: false,
            done: false,
        }
    }

    /// Make as much progress as possible without blocking.
    fn step(&mut self, mut r: &TcpStream, mut w: &TcpStream) -> io::Result<Want> {
        loop {
            if self.done {
                return Ok(Want::Nothing);
            }
            if self.pos < self.cap {
                match w.write(&self.buf[self.pos..self.cap]) {
                    Ok(0) => {
                        return Err(io::Error::new(
                            io::ErrorKind::WriteZero,
                            "write zero byte into writer",
                        ))
                    }
