                match r.read(&mut self.buf) {
                    Ok(0) => self.read_done = true,
                    Ok(n) => {
                        self.pos = 0;
                        self.cap = n;
                    }
                    Err(e) if e.kind() == io::ErrorKind::WouldBlock => return Ok(Want::Read),
                    Err(e) if e.kind() == io::ErrorKind::Interrupted => {}
                    Err(e) => return Err(e),
                }
            } else {
                w.shutdown(Shutdown::Write)?;
                self.done = true;
            }
        }
    }
}

