/// have reached EOF, or until an error occurs in either direction.
pub fn copy_bidirectional(a: &TcpStream, b: &TcpStream) -> io::Result<()> {
    a.set_nonblocking(true)?;
    b.set_nonblocking(true)?;
    let mut a_to_b = Transfer::new();
    let mut b_to_a = Transfer::new();
    loop {
        let w1 = a_to_b.step(a, b)?;
        let w2 = b_to_a.step(b, a)?;
        if a_to_b.done && b_to_a.done {
            return Ok(());
        }
        let mut a_events: i16 = 0;
        let mut b_events: i16 = 0;
        match w1 {
            Want::Read => a_events |= libc::POLLIN,
            Want::Write => b_events |= libc::POLLOUT,
            Want::Nothing => {}
        }
        match w2 {
            Want::Read => b_events |= libc::POLLIN,
            Want::Write => a_events |= libc::POLLOUT,
            Want::Nothing => {}
        }
        let mut fds = [
            libc::pollfd {
                fd: a.as_raw_fd(),
                events: a_events,
                revents: 0,
            },
            libc::pollfd {
                fd: b.as_raw_fd(),
                events: b_events,
                revents: 0,
            },
        ];
        // Only poll descriptors we are interested in.
        let (ptr, n) = if a_events == 0 {
            (fds[1..].as_mut_ptr(), 1)
        } else if b_events == 0 {
            (fds[..1].as_mut_ptr(), 1)
        } else {
            (fds.as_mut_ptr(), 2)
        };
        loop {
            let r = unsafe { libc::poll(ptr, n, -1) };
            if r < 0 {
                let err = io::Error::last_os_error();
                if err.kind() == io::ErrorKind::Interrupted {
                    continue;
                }
                return Err(err);
            }
            break;
        }
    }
}
