/// Long flags (without leading dashes) of the arguments in each subcommand's
/// argument group, in declaration order, with their usage rendering.
fn group_members(sub: &str) -> Option<&'static [(&'static str, &'static str)]> {
    match sub {
        "local" => Some(&[
            ("", "LOCAL_PORT"),
            ("local-host", "--local-host <HOST>"),
            ("to", "--to <TO>"),
            ("port", "--port <PORT>"),
            ("secret", "--secret <SECRET>"),
        ]),
        "server" => Some(&[
            ("min-port", "--min-port <MIN_PORT>"),
            ("max-port", "--max-port <MAX_PORT>"),
            ("secret", "--secret <SECRET>"),
            ("bind-addr", "--bind-addr <BIND_ADDR>"),
            ("bind-tunnels", "--bind-tunnels <BIND_TUNNELS>"),
        ]),
        _ => None,
    }
}

fn context_str(err: &clap::Error, kind: ContextKind) -> Option<String> {
    match err.get(kind) {
        Some(ContextValue::String(s)) => Some(s.clone()),
        Some(ContextValue::Strings(v)) => v.first().cloned(),
        _ => None,
    }
}

/// Adjust rendered errors so they match the reference implementation's output.
fn adjust_error(err: &mut clap::Error, cmd: &Command, args: &[OsString]) {
    let styles = cmd.get_styles().clone();
    match err.kind() {
        ErrorKind::InvalidSubcommand => {
            let has_suggestion = matches!(
                err.get(ContextKind::SuggestedSubcommand),
                Some(ContextValue::Strings(v)) if !v.is_empty()
            );
            let already = matches!(
                err.get(ContextKind::Suggested),
                Some(ContextValue::StyledStrs(v)) if !v.is_empty()
            );
            if has_suggestion && !already {
                if let Some(subcmd) = context_str(err, ContextKind::InvalidSubcommand) {
                    let name = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());
                    let invalid = styles.get_invalid();
                    let valid = styles.get_valid();
                    let tip = format!(
                        "to pass '{invalid}{subcmd}{invalid:#}' as a value, use '{valid}{name} -- {subcmd}{valid:#}'"
                    );
                    err.insert(
                        ContextKind::Suggested,
                        ContextValue::StyledStrs(vec![StyledStr::from(tip)]),
                    );
                }
            }
        }
        ErrorKind::UnknownArgument => {
            let Some(invalid) = context_str(err, ContextKind::InvalidArg) else {
                return;
            };
            if !invalid.starts_with("--") {
                return;
            }
            let Some(sub) = args.get(1).and_then(|s| s.to_str()) else {
                return;
            };
            let Some(members) = group_members(sub) else {
                return;
            };
            let suggested = context_str(err, ContextKind::SuggestedArg);
            // Locate the offending token; everything between the subcommand
            // and it was parsed successfully as a member of the group.
            let with_eq = format!("{invalid}=");
            let idx = args.iter().enumerate().skip(2).find_map(|(i, a)| {
                let a = a.to_string_lossy();
