/// Decide whether to emit ANSI styling for a stream, following the classic
/// `CLICOLOR` / `CLICOLOR_FORCE` / `NO_COLOR` conventions.
fn use_color(is_terminal: bool) -> bool {
    let clicolor = env_is("CLICOLOR", |v| v != "0");
    let clicolor_enabled = clicolor.unwrap_or(false);
    let clicolor_disabled = !clicolor.unwrap_or(true);
    let clicolor_force = env_is("CLICOLOR_FORCE", |v| v != "0").unwrap_or(false);
    let no_color = env_is("NO_COLOR", |v| !v.is_empty()).unwrap_or(false);
    let term_supports_color = env_is("TERM", |v| v != "dumb").unwrap_or(false);
    let is_ci = std::env::var_os("CI").is_some();
    (is_terminal
        && !no_color
        && !clicolor_disabled
        && (term_supports_color || clicolor_enabled || is_ci))
        || clicolor_force
}

/// Print a parse error (or help/version output) and exit the process.
pub fn exit_with(err: &clap::Error) -> ! {
    use std::io::{IsTerminal, Write};

    let styled = err.render();
    let to_stderr = err.use_stderr();
    let is_terminal = if to_stderr {
        std::io::stderr().is_terminal()
    } else {
        std::io::stdout().is_terminal()
    };
    let text = if use_color(is_terminal) {
        styled.ansi().to_string()
    } else {
        styled.to_string()
    };
    if to_stderr {
        let mut e = std::io::stderr().lock();
        let _ = e.write_all(text.as_bytes());
        let _ = e.flush();
    } else {
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(text.as_bytes());
        let _ = o.flush();
    }
    let _ = std::io::stdout().lock().flush();
    let _ = std::io::stderr().lock().flush();
    std::process::exit(err.exit_code())
