class Proc:
    def __init__(self, args, env=None):
        e = dict(os.environ)
        e.setdefault("NO_COLOR", "1")
        if env: e.update(env)
        self.p = subprocess.Popen([BIN] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=e)
        self.out = []
        self.err = []
        self.t1 = threading.Thread(target=self._rd, args=(self.p.stdout, self.out), daemon=True); self.t1.start()
        self.t2 = threading.Thread(target=self._rd, args=(self.p.stderr, self.err), daemon=True); self.t2.start()
    def _rd(self, f, acc):
        for line in iter(f.readline, b''):
            acc.append(line.decode('utf-8', 'replace'))
    def stop(self):
        if self.p.poll() is None:
            self.p.terminate()
        try:
            self.p.wait(5)
        except Exception:
            self.p.kill()
        self.t1.join(1); self.t2.join(1)
        return self.p.returncode
    def wait(self, t):
        try:
