def wait_port(port, timeout=3):
    end = time.time() + timeout
    while time.time() < end:
        try:
            s = socket.create_connection(("127.0.0.1", port), timeout=0.2); s.close(); return True
        except Exception:
            time.sleep(0.05)
    return False

def wait_listen(port, timeout=3):
    # check /proc/net/tcp for LISTEN on port (avoid connecting)
    end = time.time() + timeout
    hexp = "%04X" % port
    while time.time() < end:
        for f in ("/proc/net/tcp", "/proc/net/tcp6"):
            try:
                for line in open(f).read().splitlines()[1:]:
                    parts = line.split()
                    if parts[1].endswith(":" + hexp) and parts[3] == "0A":
                        return True
            except Exception:
                pass
        time.sleep(0.02)
    return False

def wait_free(port, timeout=5):
    end = time.time() + timeout
    hexp = "%04X" % port
    while time.time() < end:
        busy = False
        for f in ("/proc/net/tcp", "/proc/net/tcp6"):
            for line in open(f).read().splitlines()[1:]:
