    def send(self, b):
        self.s.sendall(b)

def answer(secret, challenge):
    k = hashlib.sha256(secret.encode()).digest()
    return hmac.new(k, uuid.UUID(challenge).bytes, hashlib.sha256).hexdigest()

def conn(port=7835):
