//! Bookkeeping that mirrors how an event-loop reactor hands out tokens to I/O
//! resources, so that trace-level diagnostics about socket registration can be
//! reported the same way.
//!
//! Tokens are allocated from a paged slab: page `n` holds `32 << n` slots,
//! freed slots are reused in LIFO order, and each reuse of a slot bumps a
//! 7-bit generation counter that is packed above a 24-bit slot address.

use std::ops::{Deref, DerefMut};
use std::sync::Mutex;

use crate::log::{self, Level};

const TARGET: &str = "mio::poll";
const PAGE_INITIAL_SIZE: usize = 32;
const NUM_PAGES: usize = 19;
const ADDRESS_BITS: u32 = 24;
const GENERATION_MASK: u8 = 0x7f;

struct Slot {
    generation: u8,
    next: usize,
}

struct Page {
    prev_len: usize,
    len: usize,
    slots: Vec<Slot>,
    head: usize,
    used: usize,
}

struct Slab {
    pages: Vec<Page>,
}

impl Slab {
    fn new() -> Self {
        let mut pages = Vec::with_capacity(NUM_PAGES);
        let mut prev_len = 0;
        let mut len = PAGE_INITIAL_SIZE;
        for _ in 0..NUM_PAGES {
            pages.push(Page {
                prev_len,
                len,
                slots: Vec::new(),
                head: 0,
                used: 0,
            });
            prev_len += len;
            len *= 2;
        }
        Slab { pages }
    }

    /// Allocate a slot, returning its address and generation.
    fn allocate(&mut self) -> Option<(usize, u8)> {
        for page in &mut self.pages {
            if page.used == page.len {
                continue;
            }
            if page.head < page.slots.len() {
                let idx = page.head;
                let slot = &mut page.slots[idx];
                page.head = slot.next;
                page.used += 1;
                slot.generation = slot.generation.wrapping_add(1) & GENERATION_MASK;
                return Some((page.prev_len + idx, slot.generation));
            } else if page.slots.len() < page.len {
                let idx = page.slots.len();
                page.slots.push(Slot {
                    generation: 0,
                    next: 0,
                });
                page.head += 1;
                page.used += 1;
                return Some((page.prev_len + idx, 0));
            }
        }
        None
    }

    fn release(&mut self, addr: usize) {
        for page in &mut self.pages {
            if addr >= page.prev_len && addr < page.prev_len + page.len {
                let idx = addr - page.prev_len;
                if let Some(slot) = page.slots.get_mut(idx) {
                    slot.next = page.head;
                    page.head = idx;
                    page.used -= 1;
                }
                return;
            }
        }
    }
}

static SLAB: Mutex<Option<Slab>> = Mutex::new(None);

/// A registration of an I/O resource with the (emulated) reactor.
pub struct Registration {
    addr: Option<usize>,
}

impl Registration {
    /// Register a new I/O resource for readable and writable interest.
    pub fn new() -> Self {
        let allocated = {
            let mut guard = SLAB.lock().unwrap_or_else(|e| e.into_inner());
            guard.get_or_insert_with(Slab::new).allocate()
        };
        let addr = allocated.map(|(addr, generation)| {
            let token = ((generation as u64) << ADDRESS_BITS) | addr as u64;
            log::record(
                Level::Trace,
                TARGET,
                &format!(
                    "registering event source with poller: token=Token({token}), interests=READABLE | WRITABLE"
                ),
            );
            addr
        });
        Registration { addr }
    }
}

impl Drop for Registration {
    fn drop(&mut self) {
        if let Some(addr) = self.addr.take() {
            log::record(Level::Trace, TARGET, "deregistering event source from poller");
            let mut guard = SLAB.lock().unwrap_or_else(|e| e.into_inner());
            if let Some(slab) = guard.as_mut() {
                slab.release(addr);
            }
        }
    }
}

/// An I/O object together with its reactor registration. The registration is
/// released (and reported) before the underlying descriptor is closed.
pub struct Registered<T> {
    registration: Registration,
    io: Option<T>,
}

impl<T> Registered<T> {
    /// Register an I/O object.
    pub fn new(io: T) -> Self {
        Registered {
            registration: Registration::new(),
            io: Some(io),
        }
    }
}

impl<T> Deref for Registered<T> {
    type Target = T;

    fn deref(&self) -> &T {
        self.io.as_ref().expect("I/O object present until drop")
    }
}

impl<T> DerefMut for Registered<T> {
    fn deref_mut(&mut self) -> &mut T {
        self.io.as_mut().expect("I/O object present until drop")
    }
}

impl<T> Drop for Registered<T> {
    fn drop(&mut self) {
        // Deregister first, then close the descriptor.
        drop(std::mem::replace(
            &mut self.registration,
            Registration { addr: None },
        ));
        drop(self.io.take());
    }
}
