//! UUID parsing for protocol messages.
//!
//! Accepts the simple (32 hex digits), hyphenated, braced (`{...}`) and URN
//! (`urn:uuid:...`) forms, and reports malformed input with detailed messages
//! describing what went wrong.

use std::fmt;

use serde::de::{self, Deserializer, Visitor};
use uuid::Uuid;

/// Reasons a UUID string can fail to parse.
#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    /// An unexpected character at a 1-based byte position.
    Char { character: char, index: usize },
    /// A simple-format string of the wrong length.
    SimpleLength { len: usize },
    /// The wrong number of hyphen-separated groups.
    GroupCount { count: usize },
    /// A group of the wrong length.
    GroupLength { group: usize, len: usize },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            ParseError::Char { character, index } => write!(
                f,
                "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `{character}` at {index}"
            ),
            ParseError::SimpleLength { len } => write!(
                f,
                "invalid length: expected length 32 for simple format, found {len}"
            ),
            ParseError::GroupCount { count } => {
                write!(f, "invalid group count: expected 5, found {count}")
            }
            ParseError::GroupLength { group, len } => {
                let expected = [8, 4, 4, 4, 12][group];
                write!(
                    f,
                    "invalid group length in group {group}: expected {expected}, found {len}"
                )
            }
        }
    }
}

fn hex_value(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn parse_simple(s: &[u8]) -> Option<[u8; 16]> {
    if s.len() != 32 {
        return None;
    }
    let mut out = [0u8; 16];
    for (i, pair) in s.chunks(2).enumerate() {
        out[i] = (hex_value(pair[0])? << 4) | hex_value(pair[1])?;
    }
    Some(out)
}

fn parse_hyphenated(s: &[u8]) -> Option<[u8; 16]> {
    if s.len() != 36 || s[8] != b'-' || s[13] != b'-' || s[18] != b'-' || s[23] != b'-' {
        return None;
    }
    let digits: Vec<u8> = s
        .iter()
        .enumerate()
        .filter(|(i, _)| !matches!(i, 8 | 13 | 18 | 23))
        .map(|(_, b)| *b)
        .collect();
    parse_simple(&digits)
}

fn try_parse(input: &[u8]) -> Option<[u8; 16]> {
    match (input.len(), input) {
        (32, s) => parse_simple(s),
        (36, s) => parse_hyphenated(s),
        (38, [b'{', s @ .., b'}']) => parse_hyphenated(s),
        (45, [b'u', b'r', b'n', b':', b'u', b'u', b'i', b'd', b':', s @ ..]) => parse_hyphenated(s),
        _ => None,
    }
}

/// Work out a descriptive error for an input that failed to parse.
fn describe_error(input: &str) -> ParseError {
    let (uuid_str, offset, simple) = match input.as_bytes() {
        [b'{', s @ .., b'}'] => (&input[1..1 + s.len()], 1, false),
        [b'u', b'r', b'n', b':', b'u', b'u', b'i', b'd', b':', ..] => (&input[9..], 9, false),
        _ => (input, 0, true),
    };

    let mut hyphen_count = 0;
    let mut group_bounds = [0usize; 4];
    for (index, character) in uuid_str.char_indices() {
        if character == '-' {
            if hyphen_count < 4 {
                group_bounds[hyphen_count] = index;
            }
            hyphen_count += 1;
        } else if !character.is_ascii_hexdigit() {
            return ParseError::Char {
                character,
                index: index + offset + 1,
            };
        }
    }

    if hyphen_count == 0 && simple {
        ParseError::SimpleLength { len: input.len() }
    } else if hyphen_count != 4 {
        ParseError::GroupCount {
            count: hyphen_count + 1,
        }
    } else {
        const BLOCK_STARTS: [usize; 5] = [0, 9, 14, 19, 24];
        for i in 0..4 {
            if group_bounds[i] != BLOCK_STARTS[i + 1] - 1 {
                return ParseError::GroupLength {
                    group: i,
                    len: group_bounds[i].saturating_sub(BLOCK_STARTS[i]),
                };
            }
        }
        ParseError::GroupLength {
            group: 4,
            len: input.len().saturating_sub(BLOCK_STARTS[4]),
        }
    }
}

/// Parse a UUID from any of its supported textual forms.
pub fn parse(input: &str) -> Result<Uuid, ParseError> {
    match try_parse(input.as_bytes()) {
        Some(bytes) => Ok(Uuid::from_bytes(bytes)),
        None => Err(describe_error(input)),
    }
}

struct UuidVisitor;

impl Visitor<'_> for UuidVisitor {
    type Value = Uuid;

    fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("a UUID string")
    }

    fn visit_str<E: de::Error>(self, value: &str) -> Result<Uuid, E> {
        parse(value).map_err(|e| E::custom(format_args!("UUID parsing failed: {e}")))
    }
}

/// Deserialize a UUID from a string (for use with `#[serde(deserialize_with)]`).
pub fn deserialize<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Uuid, D::Error> {
    deserializer.deserialize_str(UuidVisitor)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_all_forms() {
        let expected = Uuid::from_u128(0x67e55044_10b1_426f_9247_bb680e5fe0c8);
        for s in [
            "67e5504410b1426f9247bb680e5fe0c8",
            "67e55044-10b1-426f-9247-bb680e5fe0c8",
            "{67e55044-10b1-426f-9247-bb680e5fe0c8}",
            "urn:uuid:67e55044-10b1-426f-9247-bb680e5fe0c8",
            "67E55044-10B1-426F-9247-BB680E5FE0C8",
        ] {
            assert_eq!(parse(s), Ok(expected), "{s}");
        }
    }

    #[test]
    fn describes_errors() {
        let msg = |s: &str| parse(s).unwrap_err().to_string();
        assert_eq!(msg(""), "invalid length: expected length 32 for simple format, found 0");
        assert_eq!(msg("0000-0000"), "invalid group count: expected 5, found 2");
        assert_eq!(
            msg("urn:uuid:00000000-0000-0000-0000-00000000000"),
            "invalid group length in group 4: expected 12, found 20"
        );
        assert_eq!(
            msg("00000000--0000-0000-000000000000"),
            "invalid group length in group 1: expected 4, found 0"
        );
        assert!(msg("{\u{e9}}").ends_with("found `\u{e9}` at 2"));
    }
}
